"use client";

import { useEffect, useState } from "react";
import { useMotionValue } from "framer-motion";
import IntroAnimation, { type MorphItem } from "@/components/ui/scroll-morph-hero";
import { Section } from "@/components/ui/Section";
import { plateDataUrl } from "@/components/ui/InsightArt";
import { ScrollTrigger, useIsomorphicLayoutEffect } from "@/lib/gsap";
import { CLIENTS } from "@/data/clients";

const toItems = (withArt: boolean): MorphItem[] =>
  CLIENTS.map((c, i) => ({
    src: c.image ?? (withArt ? plateDataUrl(c.variant, i * 97 + 11) : undefined),
    title: c.name,
    subtitle: c.industry,
  }));

/**
 * The client roster as the scroll-morph arc, straight after the hero. The
 * section pins for its height and hands its scroll progress to the component, so the cards morph from the circle into the arc on ordinary page
 * scroll — no wheel capture, and it works the same with Lenis, touch, keyboard
 * and the scrollbar.
 */
export function Clients() {
  const progress = useMotionValue(0);

  // Generated art needs a canvas, so it is painted after mount; real images
  // are available immediately.
  const [items, setItems] = useState<MorphItem[]>(() => toItems(false));
  useEffect(() => {
    setItems(toItems(true));
  }, []);

  useIsomorphicLayoutEffect(() => {
    const el = document.getElementById("clients");
    if (!el) return;
    const st = ScrollTrigger.create({
      trigger: el,
      start: "top top",
      end: "bottom bottom",
      onUpdate: (self) => progress.set(self.progress),
    });
    return () => st.kill();
  }, [progress]);

  return (
    <Section id="clients" className="h-[165vh]" label="Clients">
      <div className="h-full">
        <div className="sticky top-0 h-[100svh] overflow-hidden">
          <IntroAnimation
            items={items}
            progress={progress}
            background="transparent"
            introTitle="Built for Ambitious Teams"
            introHint="SCROLL TO EXPLORE"
            title="Our Clients"
            description="From fintech and healthcare to real estate and commerce — the teams we design and engineer for, and the products we have shipped with them."
          />
        </div>
      </div>
    </Section>
  );
}
